"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the 'api' container to 750m, clearing the throttling and allowing the container to meet its CPU demand without hitting the limit.",
  "rationale": "The container is consistently hitting its 500m CPU limit (0.495 usage), causing throttling and readiness probe failures. The new version (revision 2) uses more CPU than the previous version, which had no metrics history. Increasing the limit to 750m (1.5x current) should resolve the throttling without requiring rollback or node-level changes.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-rollout_history", "ev-revision_health"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app"]
}
